TOP={}
for x in T.replace('\n','|').split('|'):
    k,n=x.strip().split(' ',1); TOP[k]=(n.rstrip('+'),n.endswith('+'))
def tags(y):
    if y==2026: return dict(zip(range(91,151),CS[y].split()))
    L=['CDP.'+t for t in CDP[y].split()]+['HIN.'+t for t in HIN[y].split()]+['ENG.'+t for t in ENG[y].split()]+GS[y].split()+CS[y].split()
    assert [len(CDP[y].split()),len(HIN[y].split()),len(ENG[y].split()),len(GS[y].split()),len(CS[y].split())]==[30,15,15,30,60],y
    return dict(zip(range(1,151),L))
for y in list(CDP)+[2026]:
    tg=tags(y); assert len(tg) in(150,60)
    for q,t in tg.items(): assert t in TOP,(y,q,t)
